import{_ as t,c as i,o as r,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const T=JSON.parse('{"title":"MODIFYING RECIPROCAL TARIFF RATES TO REFLECT TRADING PARTNER RETALIATION AND ALIGNMENT","description":"","frontmatter":{"title":"MODIFYING RECIPROCAL TARIFF RATES TO REFLECT TRADING PARTNER RETALIATION AND ALIGNMENT","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/modifying-reciprocal-tariff-rates-to-reflect-trading-partner-retaliation-and-alignment/","publishDate":"2025-04-09T23:30:00-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-10-modifying-reciprocal-tariff-rates-to-reflect-trading-partner-retaliation-and-alignment.md","filePath":"executive-orders/2025-04-10-modifying-reciprocal-tariff-rates-to-reflect-trading-partner-retaliation-and-alignment.md"}'),n={name:"executive-orders/2025-04-10-modifying-reciprocal-tariff-rates-to-reflect-trading-partner-retaliation-and-alignment.md"};function o(l,e,d,s,c,f){return r(),i("div",null,e[0]||(e[0]=[a('<h1 id="modifying-reciprocal-tariff-rates-to-reflect-trading-partner-retaliation-and-alignment" tabindex="-1">MODIFYING RECIPROCAL TARIFF RATES TO REFLECT TRADING PARTNER RETALIATION AND ALIGNMENT <a class="header-anchor" href="#modifying-reciprocal-tariff-rates-to-reflect-trading-partner-retaliation-and-alignment" aria-label="Permalink to &quot;MODIFYING RECIPROCAL TARIFF RATES TO REFLECT TRADING PARTNER RETALIATION AND ALIGNMENT&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/modifying-reciprocal-tariff-rates-to-reflect-trading-partner-retaliation-and-alignment/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/modifying-reciprocal-tariff-rates-to-reflect-trading-partner-retaliation-and-alignment/</a></p><p>Published: Thursday, April 10, 2025</p><ul><li>The President has the authority under multiple U.S. laws, including the International Emergency Economic Powers Act, to address national security threats related to trade.</li><li>Executive Order 14257 (April 2, 2025) declared a national emergency due to large and persistent U.S. trade deficits and imposed additional duties to protect the U.S. economy.</li><li>Section 4(b) of Executive Order 14257 allows for modifications to the Harmonized Tariff Schedule (HTSUS) if trading partners retaliate.</li><li>Following a PRC announcement of retaliatory tariffs, the President modified the HTSUS to raise duties on imports from China in response.</li><li>The PRC retaliated with an 84% tariff on U.S. goods effective April 10, 2025.</li><li>More than 75 foreign trading partners have approached the U.S. to address trade reciprocity, contrasting with PRC actions.</li><li>Under Section 4(c) of Executive Order 14257, the President decided to temporarily suspend duties for trading partners listed in Annex I for 90 days, except for the PRC.</li><li>Effective April 10, 2025, an additional 10% duty will apply to imports from trading partners in Annex I.</li><li>Various modifications to duty rates and descriptions in the HTSUS will take effect on April 10, including removing previous tariff rates and suspending certain provisions for 90 days.</li><li>The order aims to ensure tariffs are enforced effectively to prevent circumvention and uphold the purpose of the previous Executive Orders.</li><li>Actions are directed towards relevant government officials to implement the order, including amending regulations as necessary.</li><li>The order does not create any enforceable rights against the United States or its entities.</li></ul>',4)]))}const g=t(n,[["render",o]]);export{T as __pageData,g as default};
